function setFlow(flow){
  S.activeFlow=flow;
  if(flow)localStorage.setItem("wm_flow",flow);
  else localStorage.removeItem("wm_flow");
    localStorage.removeItem("wm_cart_done");
    S.cartDone=false;
}
function resetFlow(){
  setFlow(null);
  S.bcMenus=[];S.bcStyles=[];S.bcSuggested=[];S.cart=[];S.fridgeAdded=false;
  go("home");
}

