      <button onclick="S.cart.forEach((_,i)=>S.cart[i].checked=false);render()" style="flex:1;padding:8px;background:#f5f5f5;border:none;border-radius:10px;font-size:12px;font-weight:700;color:#888">✕ 전체해제</button>
